const CFG = {
  maxTokens: 1024,
  model: "docker.io/ai/qwen2.5:latest",
  dmrUrl: "http://host.docker.internal:12434/engines/llama.cpp/v1/chat/completions",
  graphqlUrl: "http://host.docker.internal:5000/graphql",
  tikaUrl: "http://tika:9998/tika"
};

if (typeof fetch !== "function") {
  throw new Error("Global fetch is not available in this n8n Code node runtime.");
}

async function postJson(url, body, headers = {}) {
  const res = await fetch(url, {
    method: "POST",
    headers: { "Content-Type": "application/json", ...headers },
    body: JSON.stringify(body)
  });

  const text = await res.text();

  let json;
  try {
    json = text ? JSON.parse(text) : {};
  } catch {
    throw new Error(`HTTP ${res.status} from ${url}: non-JSON response: ${text.slice(0, 1000)}`);
  }

  if (!res.ok) {
    throw new Error(`HTTP ${res.status} from ${url}: ${JSON.stringify(json).slice(0, 1500)}`);
  }

  return json;
}

async function gql(query, variables = {}) {
  const result = await postJson(CFG.graphqlUrl, { query, variables });

  if (result.errors) {
    throw new Error("GraphQL errors: " + JSON.stringify(result.errors));
  }

  return result.data;
}

function namedType(type) {
  let t = type;
  while (t && t.ofType) t = t.ofType;
  return t ? t.name : null;
}

const typeCache = new Map();

async function getInputFields(typeName) {
  if (typeCache.has(typeName)) return typeCache.get(typeName);

  const data = await gql(
    `query($name: String!) {
      __type(name: $name) {
        inputFields {
          name
          type {
            kind
            name
            ofType {
              kind
              name
              ofType {
                kind
                name
                ofType {
                  kind
                  name
                  ofType {
                    kind
                    name
                  }
                }
              }
            }
          }
        }
      }
    }`,
    { name: typeName }
  );

  const fields = data.__type?.inputFields || [];
  typeCache.set(typeName, fields);
  return fields;
}

async function getCreateSpec(entityName) {
  const data = await gql(
    `query {
      __schema {
        mutationType {
          fields {
            name
            args {
              name
              type {
                kind
                name
                ofType {
                  kind
                  name
                  ofType {
                    kind
                    name
                    ofType {
                      kind
                      name
                      ofType {
                        kind
                        name
                      }
                    }
                  }
                }
              }
            }
          }
        }
      }
    }`
  );

  const mutations = data.__schema?.mutationType?.fields || [];
  const mutationName = `create${entityName}`;

  const mutation = mutations.find(m => m.name === mutationName);
  if (!mutation) {
    throw new Error(`Could not find mutation ${mutationName}`);
  }

  const inputArg = mutation.args.find(a => a.name === "input") || mutation.args[0];
  const outerInputType = namedType(inputArg.type);
  const outerFields = await getInputFields(outerInputType);

  const wantedRowField = entityName.charAt(0).toLowerCase() + entityName.slice(1);

  const rowField =
    outerFields.find(f => f.name === wantedRowField) ||
    outerFields.find(f => f.name !== "clientMutationId");

  if (!rowField) {
    throw new Error(`Could not find row field for ${mutationName}`);
  }

  const rowInputType = namedType(rowField.type);
  const rowFields = await getInputFields(rowInputType);

  return {
    mutationName,
    outerInputType,
    rowFieldName: rowField.name,
    payloadField: wantedRowField,
    rowFields
  };
}

function getAny(obj, keys) {
  if (!obj || typeof obj !== "object") return undefined;

  for (const key of keys) {
    const exact = obj[key];
    if (exact !== undefined && exact !== null && exact !== "") return exact;

    const found = Object.keys(obj).find(k => k.toLowerCase() === key.toLowerCase());
    if (found && obj[found] !== undefined && obj[found] !== null && obj[found] !== "") {
      return obj[found];
    }
  }

  return undefined;
}

function coerce(value, field) {
  if (value === undefined || value === null || value === "") return undefined;

  const typeName = namedType(field.type);

  if (typeName === "Int") {
    const n = parseInt(String(value).replace(",", "."), 10);
    return Number.isFinite(n) ? n : undefined;
  }

  if (["Float", "BigFloat", "Decimal"].includes(typeName)) {
    const n = Number(String(value).replace(",", "."));
    return Number.isFinite(n) ? n : undefined;
  }

  return value;
}

function buildDocumentInput(fields, extracted, sourceFile, rawText) {
  const doc = extracted.document || {};
  const firstLine = (extracted.lines || [])[0] || {};
  const out = {};

  for (const field of fields) {
    const name = field.name;
    const n = name.toLowerCase();

    if (["id", "nodeid", "createdat", "updatedat"].includes(n)) continue;

    let value = getAny(doc, [name]);

    if (value === undefined) {
      if (n.includes("source") || n.includes("file")) value = sourceFile;
      else if (n.includes("document") && n.includes("type")) value = "shipment";
      else if (n.includes("type")) value = "shipment";
      else if (n.includes("shipment") && n.includes("ref")) value = doc.shipmentRef || firstLine.shipmentRef || "UNKNOWN";
      else if (n.includes("customer") && n.includes("po")) value = doc.customerPo || firstLine.customerPo || "";
      else if (n.includes("customer") && (n.includes("name") || n === "customer")) value = doc.customerName || "";
      else if (n.includes("invoice")) value = doc.invoiceNumber || "";
      else if (n.includes("date")) value = doc.shipmentDate || doc.invoiceDate || undefined;
      else if (n.includes("raw") || n.includes("text")) value = rawText;
    }

    value = coerce(value, field);
    if (value !== undefined) out[name] = value;
  }

  return out;
}

function buildLineInput(fields, line, doc, documentId) {
  const out = {};

  for (const field of fields) {
    const name = field.name;
    const n = name.toLowerCase();

    if (["id", "nodeid", "createdat", "updatedat"].includes(n)) continue;

    let value = getAny(line, [name]);

    if (value === undefined) {
      if (n === "documentid" || n === "shipmentdocumentid") value = documentId;
      else if (n.includes("product") && n.includes("code")) value = line.productCode || line.itemCode || line.sku || "UNKNOWN";
      else if (n.includes("product") && n.includes("description")) value = line.productDescription || line.description || "";
      else if (n.includes("description")) value = line.productDescription || line.description || "";
      else if (n.includes("quantity") || n === "qty") value = line.quantity || "1";
      else if (n.includes("serial")) value = line.serialNumber || line.serial || "";
      else if (n.includes("shipment") && n.includes("ref")) value = line.shipmentRef || doc.shipmentRef || "";
      else if (n.includes("customer") && n.includes("po")) value = line.customerPo || doc.customerPo || "";
      else if (n.includes("unit") && n.includes("price")) value = line.unitPrice || "";
      else if (n.includes("discount")) value = line.discount || "";
      else if (n.includes("total")) value = line.lineTotal || line.total || "";
    }

    value = coerce(value, field);
    if (value !== undefined) out[name] = value;
  }

  return out;
}

async function insertRow(spec, row) {
  const mutation = `
    mutation($input: ${spec.outerInputType}!) {
      ${spec.mutationName}(input: $input) {
        ${spec.payloadField} {
          id
        }
      }
    }
  `;

  const variables = {
    input: {
      [spec.rowFieldName]: row
    }
  };

  const data = await gql(mutation, variables);
  const inserted = data?.[spec.mutationName]?.[spec.payloadField];

  if (!inserted?.id) {
    throw new Error(`Insert failed for ${spec.mutationName}: ${JSON.stringify(data)}`);
  }

  return inserted.id;
}

function extractJson(text) {
  const fenced = text.match(/```(?:json)?\s*([\s\S]*?)```/i);
  const candidate = fenced ? fenced[1] : text.slice(text.indexOf("{"), text.lastIndexOf("}") + 1);

  if (!candidate || !candidate.trim().startsWith("{")) {
    throw new Error("LLM did not return JSON. Raw output: " + text.slice(0, 1200));
  }

  return JSON.parse(candidate);
}

async function extractWithQwen(sourceFile, documentText) {
  const prompt = `
Extract shipment data from this document.

Return ONLY valid JSON, no markdown, with this shape:

{
  "document": {
    "sourceFile": "string",
    "documentType": "shipment",
    "shipmentRef": "string",
    "customerPo": "string",
    "customerName": "string",
    "invoiceNumber": "string",
    "shipmentDate": "string"
  },
  "lines": [
    {
      "productCode": "string",
      "productDescription": "string",
      "quantity": "string",
      "serialNumber": "string",
      "shipmentRef": "string",
      "customerPo": "string",
      "unitPrice": "string",
      "discount": "string",
      "lineTotal": "string"
    }
  ]
}

Rules:
- JSON only.
- Missing values must be empty strings.
- Keep quantities as strings.
- Copy document-level shipmentRef and customerPo to each line when possible.

Source file: ${sourceFile}

Document text:
${documentText.slice(0, 30000)}
`;

  const response = await postJson(CFG.dmrUrl, {
    model: CFG.model,
    messages: [
      {
        role: "system",
        content: "You extract structured shipment data. Return valid JSON only."
      },
      {
        role: "user",
        content: prompt
      }
    ],
    max_tokens: CFG.maxTokens,
    temperature: 0,
    stream: false
  });

  const content = response?.choices?.[0]?.message?.content || "";
  const extracted = extractJson(content);

  if (!Array.isArray(extracted.lines) || extracted.lines.length === 0) {
    throw new Error("No shipment lines extracted. Extracted JSON: " + JSON.stringify(extracted));
  }

  return extracted;
}

const item = $input.first().json;

const sourceFile = item.sourceFile || item.fileName || item.filename || "manual-input.txt";
const documentText = item.documentText || item.text || item.rawText || "";

if (!documentText || !String(documentText).trim()) {
  throw new Error("No documentText/text/rawText found on input item.");
}

const extracted = await extractWithQwen(sourceFile, String(documentText));

extracted.document = extracted.document || {};
extracted.document.sourceFile = extracted.document.sourceFile || sourceFile;

const docSpec = await getCreateSpec("ShipmentDocument");
const lineSpec = await getCreateSpec("ShipmentLine");

const documentInput = buildDocumentInput(docSpec.rowFields, extracted, sourceFile, String(documentText));
const documentId = await insertRow(docSpec, documentInput);

const lineIds = [];

for (const line of extracted.lines) {
  const lineInput = buildLineInput(lineSpec.rowFields, line, extracted.document, documentId);
  const lineId = await insertRow(lineSpec, lineInput);
  lineIds.push(lineId);
}

const readCheck = await gql(
  `query {
    allShipmentLines(first: 10, orderBy: ID_DESC) {
      nodes {
        id
        documentId
        productCode
        productDescription
        quantity
        serialNumber
        shipmentRef
        customerPo
      }
    }
  }`
);

const firstLine = extracted.lines[0] || {};

return [
  {
    json: {
      ok: true,
      sourceFile,
      documentId,
      lineIds,
      insertedLines: lineIds.length,
      extracted,
      readCheck: readCheck.allShipmentLines.nodes,
      message:
        `Shipment extraction OK\n` +
        `Source: ${sourceFile}\n` +
        `Document ID: ${documentId}\n` +
        `Lines inserted: ${lineIds.length}\n` +
        `First product: ${firstLine.productCode || ""}\n` +
        `First description: ${firstLine.productDescription || ""}\n` +
        `First serial: ${firstLine.serialNumber || ""}`
    }
  }
];
